def test_find_config_with_valid_file():
    with patch('os.path.isfile') as mock_isfile, \
         patch('os.path.isdir') as mock_isdir, \
         patch('builtins.warn') as mock_warn, \
         patch('__main__._get_config_data', return_value={'key': 'value'}):

        mock_isfile.side_effect = lambda x: x == os.path.join('/test', 'config.yaml')
        mock_isdir.side_effect = lambda x: x == '/test/stop_here'

        result = _find_config('/test')

        assert result == ('/test', {'key': 'value'})

def test_find_config_with_no_files():
    with patch('os.path.isfile', return_value=False), \
         patch('os.path.isdir', return_value=False):

        result = _find_config('/test')

        assert result == ('/test', {})

def test_find_config_stopping_on_directories():
    with patch('os.path.isfile') as mock_isfile, \
         patch('os.path.isdir') as mock_isdir:

        mock_isfile.side_effect = lambda x: False
        mock_isdir.side_effect = lambda x: x == '/test/stop_here'

        result = _find_config('/test')

        assert result == ('/test', {})

def test_find_config_depth_limit():
    with patch('os.path.isfile', return_value=False), \
         patch('os.path.isdir', side_effect=lambda x: x in ['/test', '/test/level1', '/test/level1/level2']):

        result = _find_config('/test/level1/level2/level3/level4/level5')

        assert result == ('/test/level1/level2/level3/level4/level5', {})

